register_shutdown_function(static function()use($uid,$wpdb,$clean,$expected){$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.ZMP_President_Mandate::table_name().' WHERE user_id=%d ORDER BY id DESC LIMIT 1',$uid));$events=$row?$wpdb->get_results($wpdb->prepare('SELECT event_type FROM '.ZMP_President_Mandate::audit_table_name().' WHERE mandate_id=%d ORDER BY id',(int)$row->id)):[];$u=get_userdata($uid);$roles=$u?(array)$u->roles:[];$roles_ok=$u&&count(array_diff($expected,$roles))===0;$president_absent=$u&&!in_array('zmp_president',$roles,true);$out=['test'=>'stacked member appointment','status'=>$row->status??'missing','start_date'=>$row->start_date??'','event_types'=>array_map(static fn($e)=>$e->event_type,$events),'stacked_roles_retained'=>$roles_ok,'president_role_absent_until_start'=>$president_absent,'roles_after_scheduling'=>$roles];$pass=(bool)$row&&$row->status==='scheduled'&&count($events)===1&&$events[0]->event_type==='appointed'&&$roles_ok&&$president_absent;$clean();$out['exact_cleanup']=!get_userdata($uid)&&!(int)$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.ZMP_President_Mandate::table_name().' WHERE user_id=%d',$uid));WP_CLI::log(wp_json_encode($out));if(!$pass||empty($out['exact_cleanup']))WP_CLI::error('stacked appointment or cleanup failed');});
